const d = $json.body ?? $json;
if (d.approved !== true) throw new Error('Bloqueado: aprovação explícita obrigatória.');
const content_id = String(d.content_id ?? '').trim();
const idempotency_key = String(d.idempotency_key ?? '').trim();
const caption = String(d.caption ?? '').trim();
if (!content_id || !idempotency_key || !caption) throw new Error('content_id, idempotency_key e caption são obrigatórios.');
// Só liberar redes confirmadas na conexão Metricool atual. Instagram fica bloqueado até confirmar perfil institucional.
const allowed = new Set(['youtube','tiktok','facebook']);
const requested = Array.isArray(d.channels) ? [...new Set(d.channels.map(v=>String(v).toLowerCase()))] : [];
const channels = requested.filter(v=>allowed.has(v));
const blocked_channels = requested.filter(v=>!allowed.has(v));
if (!channels.length) throw new Error('Nenhum canal aprovado/conectado. Permitidos nesta fase: Facebook, TikTok e YouTube. Instagram permanece bloqueado até confirmar o perfil institucional.');
return [{json:{content_id,idempotency_key,caption,channels,blocked_channels,approved:true,status:'queued_not_published',publish_confirmed:false,received_at:new Date().toISOString(),instruction:'Esta é somente uma fila validada; ainda não publica. Conecte adaptador autenticado e confirme a publicação na plataforma.'}}];
